urlset:
{% for page in pages %}

  https://{{ clinic.domain_name|default:"www.yourclinic.com" }}/site/{{ clinic.slug }}/{{ page.slug }}
  {{ page.updated_at|date:"Y-m-d" }}
  weekly
  {% if page.page_type == 'home' %}1.0{% elif page.page_type == 'appointment' %}0.9{% else %}0.8{% endif %}

{% endfor %}
